//   with N), never by the write itself. That asymmetry is the whole pitch
//   of the strategy, so retro() deliberately does NOT depend on retroDepth.
const deltasModel: CostModel = {
  key: 'deltas',
  storage: (p) => p.facts,
  read: (p) => p.facts,
  append: () => 1,
  retro: () => 1,
